CREATE TABLE IF NOT EXISTS period_close_reviews (
  id INTEGER PRIMARY KEY,
  packet_id INTEGER NOT NULL REFERENCES period_close_readiness_packets(id),
  packet_hash TEXT NOT NULL REFERENCES period_close_readiness_packets(packet_hash),
  reviewer_actor TEXT NOT NULL,
  reviewer_principal TEXT,
  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP
);
CREATE INDEX IF NOT EXISTS idx_period_close_reviews_packet ON period_close_reviews(packet_id,id);
CREATE TRIGGER IF NOT EXISTS period_close_reviews_no_update BEFORE UPDATE ON period_close_reviews BEGIN SELECT RAISE(ABORT, 'period close reviews are append-only'); END;
CREATE TRIGGER IF NOT EXISTS period_close_reviews_no_delete BEFORE DELETE ON period_close_reviews BEGIN SELECT RAISE(ABORT, 'period close reviews are append-only'); END;
